import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"No oversized files in version control","description":"","frontmatter":{},"headers":[],"relativePath":"reference/rules/max-file-size.md","filePath":"reference/rules/max-file-size.md"}`),a={name:`reference/rules/max-file-size.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="no-oversized-files-in-version-control" tabindex="-1">No oversized files in version control <a class="header-anchor" href="#no-oversized-files-in-version-control" aria-label="Permalink to “No oversized files in version control”">​</a></h1><p>Files above the configured budget are usually build output, database dumps, screenshots or vendored binaries committed by mistake.</p><h2 id="why-it-is-a-rule" tabindex="-1">Why it is a rule <a class="header-anchor" href="#why-it-is-a-rule" aria-label="Permalink to “Why it is a rule”">​</a></h2><p>A large file bloats every clone of the repository permanently. Deleting it later does not remove it from history, so the only cheap moment to catch it is before it lands.</p><h2 id="what-is-expected" tabindex="-1">What is expected <a class="header-anchor" href="#what-is-expected" aria-label="Permalink to “What is expected”">​</a></h2><p>Commit the source, not the artifact. Generated output belongs in <code>.gitignore</code>.</p><h2 id="if-the-file-must-be-tracked" tabindex="-1">If the file must be tracked <a class="header-anchor" href="#if-the-file-must-be-tracked" aria-label="Permalink to “If the file must be tracked”">​</a></h2><p>Some generated files legitimately have to be committed, for example a lockfile or a wrapper jar. Add those paths to the rule&#39;s <code>exclude</code> globs, with a comment saying why.</p>`,8)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};